import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  FaArrowRight,
  FaBaby,
  FaHeadset,
  FaHome,
  FaLaptop,
  FaMobileAlt,
  FaSearch,
  FaShieldAlt,
  FaShoppingBasket,
  FaSprayCan,
  FaTags,
  FaTruck,
  FaTshirt,
  FaUndoAlt
} from 'react-icons/fa';
import { getProducts } from '../services/api';
import { useTheme } from '../context/ThemeContext';

const fallbackProducts = [
  { _id: 'demo-grocery', name: 'Daily Grocery Pack', brand: 'Pinqoza', category: 'groceries', price: 499, unit: 'pack', ratings: 4.6, numReviews: 128, stock: 25 },
  { _id: 'demo-fashion', name: 'Classic Cotton T-Shirt', brand: 'UrbanWear', category: 'fashion', price: 399, unit: 'piece', ratings: 4.4, numReviews: 86, stock: 18 },
  { _id: 'demo-mobile', name: 'Smartphone Essentials Kit', brand: 'Techly', category: 'electronics', price: 899, unit: 'set', ratings: 4.7, numReviews: 204, stock: 14 },
  { _id: 'demo-beauty', name: 'Glow Care Combo', brand: 'PureSkin', category: 'beauty', price: 699, unit: 'combo', ratings: 4.5, numReviews: 91, stock: 30 }
];

const HomeRebuild = () => {
  const { isDarkMode } = useTheme();
  const navigate = useNavigate();
  const [searchDraft, setSearchDraft] = useState('');
  const [sections, setSections] = useState({
    trending: [],
    bestSellers: [],
    dailyNeeds: []
  });
  const [loading, setLoading] = useState(true);

  const categories = useMemo(
    () => [
      { label: 'Grocery', key: 'groceries', icon: FaShoppingBasket },
      { label: 'Fashion', key: 'fashion', icon: FaTshirt },
      { label: 'Mobiles', key: 'electronics', icon: FaMobileAlt },
      { label: 'Electronics', key: 'electronics', icon: FaLaptop },
      { label: 'Beauty', key: 'beauty', icon: FaSprayCan },
      { label: 'Home', key: 'home', icon: FaHome },
      { label: 'Kids', key: 'kids', icon: FaBaby },
      { label: 'Offers', key: '', sort: 'rating_desc', icon: FaTags }
    ],
    []
  );

  const trustBadges = useMemo(
    () => [
      { title: 'Fast Delivery', text: 'Quick delivery on daily essentials.', icon: FaTruck },
      { title: 'Secure Payment', text: 'Checkout protected with safe payments.', icon: FaShieldAlt },
      { title: 'Easy Return', text: 'Simple replacement support.', icon: FaUndoAlt },
      { title: 'Real Support', text: 'Help when your order needs attention.', icon: FaHeadset }
    ],
    []
  );

  useEffect(() => {
    let mounted = true;

    const loadHomeProducts = async () => {
      try {
        setLoading(true);
        const [trendingRes, bestRes, dailyRes] = await Promise.all([
          getProducts({ sort: 'rating_desc', limit: 8 }),
          getProducts({ sort: 'newest', limit: 8 }),
          getProducts({ category: 'groceries', limit: 8 })
        ]);

        if (!mounted) return;

        setSections({
          trending: trendingRes.data?.products || [],
          bestSellers: bestRes.data?.products || [],
          dailyNeeds: dailyRes.data?.products || []
        });
      } catch (error) {
        if (!mounted) return;
        setSections({
          trending: fallbackProducts,
          bestSellers: fallbackProducts,
          dailyNeeds: fallbackProducts
        });
      } finally {
        if (mounted) setLoading(false);
      }
    };

    loadHomeProducts();

    return () => {
      mounted = false;
    };
  }, []);

  const goToProducts = (params = {}) => {
    const searchParams = new URLSearchParams(params);
    navigate(`/products${searchParams.toString() ? `?${searchParams.toString()}` : ''}`);
  };

  const submitSearch = (event) => {
    event.preventDefault();
    const query = searchDraft.trim();
    if (query) goToProducts({ search: query });
  };

  const ProductTile = ({ product }) => (
    <Link
      to={`/product/${product._id}`}
      className={`group overflow-hidden rounded-xl border transition hover:-translate-y-0.5 hover:shadow-md ${isDarkMode ? 'bg-gray-900 border-white/10 hover:shadow-black/30' : 'bg-white border-gray-200/80 hover:border-primary-200 hover:shadow-gray-200'}`}
    >
      <div className={`aspect-[1.2] ${isDarkMode ? 'bg-white/5' : 'bg-gray-50'} flex items-center justify-center`}>
        {product.image ? (
          <img src={product.image} alt={product.name} className="h-full w-full object-contain p-4 transition group-hover:scale-[1.03]" loading="lazy" />
        ) : (
          <div className={`grid h-14 w-14 place-items-center rounded-xl text-xl font-black ${isDarkMode ? 'bg-white/10 text-primary-200' : 'bg-primary-50 text-primary-700'}`}>
            {String(product.name || 'P').charAt(0)}
          </div>
        )}
      </div>
      <div className="p-3">
        <div className={`text-[11px] font-semibold capitalize ${isDarkMode ? 'text-gray-500' : 'text-gray-500'}`}>
          {product.brand || 'Pinqoza'}
        </div>
        <div className={`mt-1 min-h-[36px] text-sm font-semibold leading-snug line-clamp-2 ${isDarkMode ? 'text-gray-100' : 'text-gray-800'}`}>
          {product.name}
        </div>
        <div className={`mt-1 inline-flex rounded-full px-2 py-1 text-[11px] font-semibold capitalize ${isDarkMode ? 'bg-white/5 text-gray-400' : 'bg-gray-100 text-gray-500'}`}>
          {product.category || 'Product'}
        </div>
        <div className="mt-2 flex items-center justify-between gap-2">
          <div>
            <div className={`text-base font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-950'}`}>Rs. {product.price}</div>
            <div className={`text-[11px] ${isDarkMode ? 'text-gray-500' : 'text-gray-500'}`}>/{product.unit || 'unit'}</div>
          </div>
          <span className="rounded-lg bg-yellow-300 px-2.5 py-1.5 text-xs font-extrabold text-gray-950 transition group-hover:bg-yellow-400">
            Add
          </span>
        </div>
      </div>
    </Link>
  );

  const renderProductSection = (title, subtitle, products, link) => (
    <section className="py-8">
      <div className="mb-4 flex items-end justify-between gap-4">
        <div>
          <h2 className={`text-xl md:text-2xl font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>{title}</h2>
          <p className={`mt-1 text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>{subtitle}</p>
        </div>
        <Link to={link} className="shrink-0 text-sm font-bold text-primary-600 hover:text-primary-700 dark:text-primary-300">
          View all
        </Link>
      </div>

      {loading ? (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 md:gap-4">
          {Array.from({ length: 4 }).map((_, index) => (
            <div
              key={index}
              className={`h-56 rounded-xl animate-pulse ${isDarkMode ? 'bg-white/10' : 'bg-gray-200'}`}
            />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 md:gap-4">
          {(products.length ? products : fallbackProducts).slice(0, 10).map((product, index) => (
            <ProductTile key={product._id || index} product={product} />
          ))}
        </div>
      )}
    </section>
  );

  return (
    <div className="pb-8">
      <section className="grid lg:grid-cols-[1.08fr_0.92fr] gap-8 items-center py-3 md:py-6">
        <div>
          <div className={`inline-flex items-center gap-2 rounded-full px-3 py-1 text-xs font-bold ${isDarkMode ? 'bg-white/10 text-cyan-200' : 'bg-primary-50 text-primary-700'}`}>
            <FaTags className="h-3.5 w-3.5" />
            One store for everyday shopping
          </div>
          <h1 className={`mt-4 text-4xl md:text-5xl font-extrabold leading-tight ${isDarkMode ? 'text-white' : 'text-gray-950'}`}>
            Everything you need, one click away
          </h1>
          <p className={`mt-4 max-w-2xl text-base md:text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
            Grocery, fashion, electronics, beauty, home essentials and daily needs in one clean shopping experience.
          </p>

          <form onSubmit={submitSearch} className="mt-6 max-w-2xl">
            <div className={`flex items-center gap-2 rounded-2xl border p-2 shadow-sm ${isDarkMode ? 'bg-gray-900 border-white/10' : 'bg-white border-gray-200'}`}>
              <div className={`grid h-11 w-11 place-items-center rounded-xl ${isDarkMode ? 'bg-white/10 text-gray-300' : 'bg-gray-100 text-gray-500'}`}>
                <FaSearch className="h-4 w-4" />
              </div>
              <input
                value={searchDraft}
                onChange={(event) => setSearchDraft(event.target.value)}
                placeholder="Search grocery, clothes, mobiles and more"
                className={`min-w-0 flex-1 bg-transparent px-1 py-3 text-sm md:text-base outline-none ${isDarkMode ? 'text-white placeholder:text-gray-500' : 'text-gray-900 placeholder:text-gray-400'}`}
              />
              <button type="submit" className="h-11 rounded-xl bg-gray-950 px-5 text-sm font-bold text-white hover:bg-gray-800 dark:bg-white dark:text-gray-950 dark:hover:bg-gray-200">
                Search
              </button>
            </div>
          </form>

          <div className="mt-5 flex flex-wrap gap-2">
            {['Rice', 'Shoes', 'Phone', 'Serum', 'Bedsheet'].map((item) => (
              <button
                key={item}
                type="button"
                onClick={() => goToProducts({ search: item })}
                className={`rounded-full border px-3 py-1.5 text-xs font-semibold transition ${isDarkMode ? 'border-white/10 text-gray-300 hover:bg-white/10' : 'border-gray-200 text-gray-700 hover:bg-gray-100'}`}
              >
                {item}
              </button>
            ))}
          </div>

          <div className="mt-6 flex flex-wrap gap-3">
            <button
              type="button"
              onClick={() => goToProducts()}
              className="inline-flex items-center gap-2 rounded-xl bg-gray-950 px-5 py-3 text-sm font-bold text-white transition hover:bg-gray-800 dark:bg-white dark:text-gray-950 dark:hover:bg-gray-200"
            >
              Shop now <FaArrowRight className="h-3.5 w-3.5" />
            </button>
            <button
              type="button"
              onClick={() => goToProducts({ sort: 'rating_desc' })}
              className={`rounded-xl border px-5 py-3 text-sm font-bold transition ${isDarkMode ? 'border-white/10 text-gray-200 hover:bg-white/10' : 'border-gray-200 text-gray-800 hover:bg-white'}`}
            >
              Today's deals
            </button>
          </div>
        </div>

        <div className="space-y-3">
          <div className={`mb-3 rounded-xl p-4 ${isDarkMode ? 'bg-white/5 text-white' : 'bg-gray-950 text-white'}`}>
            <div className="text-xs font-bold uppercase text-yellow-200">Live offer</div>
            <div className="mt-1 text-xl font-extrabold">Smart shopping starts here</div>
            <div className="mt-1 text-sm opacity-80">Fresh deals across daily needs, fashion and tech.</div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            {[
              { label: 'Grocery', offer: 'Daily needs', color: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-500/20 dark:text-emerald-200', icon: FaShoppingBasket },
              { label: 'Fashion', offer: 'New styles', color: 'bg-rose-100 text-rose-800 dark:bg-rose-500/20 dark:text-rose-200', icon: FaTshirt },
              { label: 'Mobiles', offer: 'Smart deals', color: 'bg-sky-100 text-sky-800 dark:bg-sky-500/20 dark:text-sky-200', icon: FaMobileAlt },
              { label: 'Home', offer: 'Essentials', color: 'bg-amber-100 text-amber-800 dark:bg-amber-500/20 dark:text-amber-200', icon: FaHome }
            ].map((item) => {
              const Icon = item.icon;
              return (
                <button
                  key={item.label}
                  type="button"
                  onClick={() => goToProducts({ category: item.label === 'Mobiles' ? 'electronics' : item.label.toLowerCase() })}
                  className={`aspect-[1.1] rounded-xl p-4 text-left transition hover:-translate-y-0.5 ${item.color}`}
                >
                  <Icon className="h-7 w-7" />
                  <div className="mt-4 text-lg font-extrabold">{item.label}</div>
                  <div className="text-sm font-semibold opacity-80">{item.offer}</div>
                </button>
              );
            })}
          </div>
        </div>
      </section>

      <section className="py-5">
        <div className="mb-3 flex items-center justify-between">
          <h2 className={`text-lg font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Shop by category</h2>
          <Link to="/products" className="text-sm font-bold text-primary-600 hover:text-primary-700 dark:text-primary-300">
            Explore all
          </Link>
        </div>
        <div className="flex gap-3 overflow-x-auto pb-2 md:grid md:grid-cols-4 lg:grid-cols-8 md:overflow-visible">
          {categories.map((category) => {
            const Icon = category.icon;
            return (
              <button
                key={category.label}
                type="button"
                onClick={() => goToProducts(category.key ? { category: category.key } : { sort: category.sort })}
                className={`min-w-[96px] rounded-xl border p-3 text-center transition hover:-translate-y-0.5 ${isDarkMode ? 'bg-gray-900 border-white/10 text-gray-200 hover:bg-white/10' : 'bg-white border-gray-200 text-gray-800 hover:border-primary-200 hover:bg-primary-50/30'}`}
              >
                <span className={`mx-auto grid h-11 w-11 place-items-center rounded-xl ${isDarkMode ? 'bg-white/10 text-primary-300' : 'bg-primary-50 text-primary-700'}`}>
                  <Icon className="h-5 w-5" />
                </span>
                <span className="mt-2 block text-xs font-bold">{category.label}</span>
              </button>
            );
          })}
        </div>
      </section>

      {renderProductSection('Trending Now', 'Popular picks customers are checking today.', sections.trending, '/products?sort=rating_desc')}

      <section className="grid md:grid-cols-2 gap-4 py-4">
        <Link to="/products?category=fashion" className="rounded-2xl bg-gray-950 p-6 text-white transition hover:bg-gray-900">
          <div className="text-sm font-bold text-rose-200">Fashion Deals</div>
          <div className="mt-2 text-2xl font-extrabold">Fresh styles for every day</div>
          <div className="mt-5 inline-flex rounded-xl bg-white px-4 py-2 text-sm font-bold text-gray-950">Shop fashion</div>
        </Link>
        <Link to="/products?category=electronics" className="rounded-2xl bg-primary-700 p-6 text-white transition hover:bg-primary-800">
          <div className="text-sm font-bold text-cyan-100">Gadget Offers</div>
          <div className="mt-2 text-2xl font-extrabold">Smart tech for your home</div>
          <div className="mt-5 inline-flex rounded-xl bg-white px-4 py-2 text-sm font-bold text-primary-800">Explore gadgets</div>
        </Link>
      </section>

      {renderProductSection('Best Sellers', 'Items with strong demand and fast movement.', sections.bestSellers, '/products?sort=newest')}
      {renderProductSection('Daily Needs', 'Groceries and essentials made easy.', sections.dailyNeeds, '/products?category=groceries')}

      <section className="grid grid-cols-2 lg:grid-cols-4 gap-3 pt-6">
        {trustBadges.map((badge) => {
          const Icon = badge.icon;
          return (
            <div key={badge.title} className={`rounded-xl border p-4 ${isDarkMode ? 'bg-gray-900 border-white/10' : 'bg-white border-gray-200'}`}>
              <Icon className={`h-6 w-6 ${isDarkMode ? 'text-primary-300' : 'text-primary-600'}`} />
              <div className={`mt-3 font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>{badge.title}</div>
              <div className={`mt-1 text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>{badge.text}</div>
            </div>
          );
        })}
      </section>
    </div>
  );
};

export default HomeRebuild;
